item.text:
{
  "ticker": "SRVCABLE",
  "as_of": "2026-09-23",
  "snapshot": [
    {
      "text": "Sarvottam Cables Ltd manufactures power cables, wires and conductors; its MD is Anil Deshpande.",
      "evidence": [
        {
          "source_id": "S3",
          "quote": "Sarvottam Cables Ltd (NSE: SRVCABLE), a manufacturer of power cables, wires and conductors"
        },
        {
          "source_id": "S3",
          "quote": "Managing Director Mr. Anil Deshpande"
        }
      ]
    },
    {
      "text": "Q1 FY27 consolidated revenue was ₹1,248 crore, up 18.0% year over year.",
      "evidence": [
        {
          "source_id": "S3",
          "quote": "| Revenue from operations | 1,248 | 1,058 | +18.0% |"
        }
      ]
    },
    {
      "text": "Quarterly profit after tax rose 5.9% to ₹82 crore.",
      "evidence": [
        {
          "source_id": "S3",
          "quote": "| Profit after tax | 82 | 77 | +5.9% |"
        }
      ]
    }
  ],
  "bull_case": [
    {
      "text": "The larger order book supports revenue visibility; conversion remains uncertain.",
      "evidence": [
        {
          "source_id": "S3",
          "quote": "Order book stood at ₹3,900 crore as of 30 June 2026, up from ₹3,150 crore a year ago."
        }
      ]
    },
    {
      "text": "Management expects Bharuch to add approximately 30% capacity, with commercial production scheduled for Q3 FY27.",
      "evidence": [
        {
          "source_id": "S3",
          "quote": "The new Bharuch (Gujarat) plant, adding about 30% to cable capacity, is on track to begin commercial production in Q3 FY27."
        }
      ]
    }
  ],
  "bear_case": [
    {
      "text": "EBITDA margin fell 170 basis points; management says contractual price resets lag costs.",
      "evidence": [
        {
          "source_id": "S3",
          "quote": "| EBITDA margin | 11.2% | 12.9% | −170 bps |"
        },
        {
          "source_id": "S2",
          "quote": "About two-thirds of our contracts have price-variation clauses, but they reset with a lag of one to two quarters."
        }
      ]
    },
    {
      "text": "CFO Meera Iyer reported slower collections, increasing working-capital pressure.",
      "evidence": [
        {
          "source_id": "S2",
          "quote": "**Meera Iyer (CFO):** Yes, receivable days increased from 78 to 96 over the last year."
        }
      ]
    },
    {
      "text": "A ₹46.3 crore GST demand creates exposure; the company's favorable legal assessment and intended appeal do not establish the outcome.",
      "evidence": [
        {
          "source_id": "S7",
          "quote": "raising a demand of **₹46.3 crore** (including interest and penalty)"
        },
        {
          "source_id": "S7",
          "quote": "The Company believes it has a strong case on merits, based on legal advice, and intends to file an appeal before the appropriate authority."
        }
      ]
    }
  ],
  "open_questions": [
    {
      "text": "What explains the news revenue discrepancy? The original company filing takes precedence; no reconciliation is supplied.",
      "evidence": [
        {
          "source_id": "S1",
          "quote": "Revenue from operations rose to **₹1,428 crore**, a 35% increase"
        },
        {
          "source_id": "S3",
          "quote": "| Revenue from operations | 1,248 | 1,058 | +18.0% |"
        }
      ]
    },
    {
      "text": "Has promoter pledging changed since June? Prefer the newer exchange filing's 4.1%; the March 2024 report's 35% is historical, not current.",
      "evidence": [
        {
          "source_id": "S8",
          "quote": "| Of which pledged (as % of promoter holding) | 4.1% | 6.0% | 11.5% |"
        },
        {
          "source_id": "S4",
          "quote": "pledged with lenders to 35%, up from 22% six months ago"
        }
      ]
    }
  ],
  "source_decisions": [
    {
      "source_id": "S1",
      "disposition": "context",
      "reason": "Same entity; secondary revenue figures conflict with S3."
    },
    {
      "source_id": "S2",
      "disposition": "use",
      "reason": "Official transcript; matching MD corroborates identity. Attribute management statements."
    },
    {
      "source_id": "S3",
      "disposition": "use",
      "reason": "Ticker, legal name, business and MD establish identity; primary quarterly figures."
    },
    {
      "source_id": "S4",
      "disposition": "context",
      "reason": "Historical pledge report superseded by S8 for current facts."
    },
    {
      "source_id": "S5",
      "disposition": "exclude",
      "reason": "Unsupported promotion, erroneous growth claim and embedded instructions."
    },
    {
      "source_id": "S6",
      "disposition": "exclude",
      "reason": "Different entity: TV/broadband operator Sarvottam Cable Network, owned by Suresh Patil."
    },
    {
      "source_id": "S7",
      "disposition": "use",
      "reason": "Recent exchange disclosure; legal confidence remains company opinion."
    },
    {
      "source_id": "S8",
      "disposition": "use",
      "reason": "Latest supplied exchange shareholding disclosure, dated June 2026."
    }
  ]
}
